// Decide which follow-up touch is due for each lead.
// Touches: day 1 (24h), day 3 (72h), day 5 (120h).
const now = Date.now();
const out = [];
for (const item of items) {
  const l = item.json;
  const ageH = (now - new Date(l.created_at).getTime()) / 36e5;
  let touch = null;
  if (ageH >= 24 && ageH < 25)    touch = 'day1';
  else if (ageH >= 72 && ageH < 73)  touch = 'day3';
  else if (ageH >= 120 && ageH < 121) touch = 'day5';
  if (touch) out.push({ json: { ...l, touch } });
}
return out;

const templates = {
  mtr: {
    day1: {
      subject: 'Still looking for furnished housing?',
      body: 'Hey {{name}} — did last night\'s availability packet come through? I can also text photos of any unit that caught your eye. Just reply with the hospital + start date.'
    },
    day3: {
      subject: 'A few units just freed up near your hospital',
      body: 'Quick update — two of our Sacramento 1BRs came back on the calendar for the window you mentioned. Want me to hold one for 24 hours while you confirm your contract?'
    },
    day5: {
      subject: 'Last check before I release your hold',
      body: 'Just touching base once more — if timing shifted on your assignment, I can pull a new list for the new dates. Otherwise I\'ll close out your inquiry so we\'re not cluttering your inbox.'
    }
  },
  cleaning: {
    day1: {
      subject: 'Your cleaning quote — anything to adjust?',
      body: 'Hey {{name}} — want me to tweak the scope? Some hosts add laundry pickup or mid-stay resets, happy to bundle those in.'
    },
    day3: {
      subject: 'Opening this week for your unit',
      body: 'I have two same-day slots open this week in {{city}}. Want to book one as a trial run? If we don\'t meet your standard, the first clean is on us.'
    },
    day5: {
      subject: 'Closing out your quote',
      body: 'Hey {{name}} — I\'ll close out your quote at the end of the week unless you\'d like to revisit it. Reply STAY and I\'ll hold it another 30 days.'
    }
  }
};

const lead = $json;
const t = templates[lead.funnel_source]?.[lead.touch];
if (!t) return [];
return [{ json: {
  ...lead,
  subject: t.subject,
  body: t.body.replace(/{{name}}/g, (lead.name||'').split(' ')[0] || 'there').replace(/{{city}}/g, lead.city||'Sacramento')
}}];
